const readings=[
 {title:'欲擒故纵',sub:'给对方出口，给自己主动权',source:'三十六计 / 攻战计',quote:'“逼则反兵，走则减势。紧随勿迫，累其气力，消其斗志，散而后擒之。兵不血刃。”',note:'逼得太紧会引发反弹；适度留出口，反而能降低抵抗。真正的主动，不是把对方逼到墙角，而是让局势朝你希望的方向发展。',matter:'适合处理项目延期、谈判僵局、资源不足：不要继续在原来的冲突点上加压，先改变节奏、议题或行动顺序，让对方的阻力自然下降。',people:'适合处理同事拖延、合作方防御、家庭争执：先理解对方在保护什么，再提供一个能接受的选择，同时明确时间、责任和后果。',history:'故事中，弱势一方用反常的镇定制造疑虑，让对方不敢贸然进攻。它提醒我们：信息不足时，人会用自己的恐惧补全事实。'},
 {title:'釜底抽薪',sub:'别和表面力量硬碰，先找到真正的燃料',source:'三十六计 / 混战计',quote:'“不敌其力，而消其势，兑下乾上之象。”',note:'不与对方的表面力量正面硬拼，转而削弱它的资源、动力或补给。',matter:'项目反复延期时，先查返工源、需求变更和决策瓶颈，而不是单纯要求团队加班。',people:'当一个人持续防御，先降低让他防御的威胁感；把“你为什么不配合”改成“什么条件能让你放心推进”。',history:'赤壁之战不只是火攻的技巧，更是对曹军水土不服、连船成阵、骄傲轻敌等结构弱点的利用。'},
 {title:'知彼知己',sub:'先知道自己和对方在什么位置',source:'孙子兵法 / 谋攻篇',quote:'“知彼知己，百战不殆；不知彼而知己，一胜一负；不知彼不知己，每战必殆。”',note:'对自己的能力、资源和边界有清醒认识，同时掌握对方真实需求与约束。',matter:'做方案前先列资源、时间、能力和最坏结果，避免只凭热情下注。',people:'不要把对方的拒绝直接解释成恶意，先区分利益冲突、信息差、身份压力和情绪反应。',history:'刘邦与项羽的差异，不只在勇力，也在于对自身长处和团队结构的判断不同。'}
];
const chapters=['始计篇','作战篇','谋攻篇','军形篇','兵势篇','虚实篇','军争篇','九变篇','行军篇','地形篇','九地篇','火攻篇','用间篇'];
const plans=['瞒天过海','围魏救赵','借刀杀人','以逸待劳','趁火打劫','声东击西','无中生有','暗度陈仓','隔岸观火','笑里藏刀','李代桃僵','顺手牵羊','打草惊蛇','借尸还魂','调虎离山','欲擒故纵','抛砖引玉','擒贼擒王','釜底抽薪','混水摸鱼','金蝉脱壳','关门捉贼','远交近攻','假道伐虢','偷梁换柱','指桑骂槐','假痴不癫','上屋抽梯','树上开花','反客为主','美人计','空城计','反间计','苦肉计','连环计','走为上计'];
let index=0, mode='matter', notes=JSON.parse(localStorage.getItem('兵法-notes')||'[]'), currentReading=readings[0], currentBook='sunzi';
const $=id=>document.getElementById(id);
function render(){const r=currentReading;$('page-title').textContent='今天读：'+r.title;$('page-subtitle').textContent=r.sub;$('quote-source').textContent=r.source;$('quote').textContent=r.quote;$('note-text').textContent=r.note;$('matter-text').textContent=r.matter;$('people-text').textContent=r.people;$('history-title').textContent=r.historyTitle||'历史镜像';$('history-text').textContent=r.history;$('card-num').textContent=String(index+1).padStart(2,'0');const total=currentBook==='plans'?36:13;$('progress-text').textContent=Math.round((index+1)/total*100)+'%';$('progress-bar').style.width=((index+1)/total*100)+'%';document.querySelectorAll('.chapter').forEach((x,i)=>x.classList.toggle('selected',i===index));loadDraft();}
function loadDraft(){const n=notes.find(x=>x.title===currentReading.title);$('understanding').value=n?.understanding||'';$('scenario').value=n?.scenario||'';$('experiment').value=n?.experiment||'';}
function save(){const r=readings[index], item={title:r.title,understanding:$('understanding').value,scenario:$('scenario').value,experiment:$('experiment').value,date:new Date().toLocaleDateString('zh-CN')};notes=[item,...notes.filter(x=>x.title!==r.title)];localStorage.setItem('兵法-notes',JSON.stringify(notes));$('save-state').textContent='已保存 · '+item.date;renderRecent();}
function renderRecent(){const box=$('recent-list');box.innerHTML=notes.length?notes.slice(0,4).map(n=>`<div class="recent-item"><strong>${n.title}</strong><p>${n.understanding||'已保存阅读卡'} · ${n.date}</p></div>`).join(''):'<div class="empty">还没有阅读卡。读完第一条就保存下来吧。</div>';}
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));});
function renderChapters(items,title,count){currentBook=title==='三十六计'?'plans':'sunzi';$('chapter-list').innerHTML='';$('index-title').textContent=title;$('index-count').textContent=count;items.forEach((c,i)=>{const b=document.createElement('button');b.className='chapter';b.textContent=`${String(i+1).padStart(2,'0')}  ${c}`;b.onclick=()=>{index=i;currentReading=currentBook==='plans'?{title:c,sub:'三十六计 / '+(i<6?'胜战计':i<12?'敌战计':i<18?'攻战计':i<24?'混战计':i<30?'并战计':'败战计'),source:'三十六计 / '+(i<6?'胜战计':i<12?'敌战计':i<18?'攻战计':i<24?'混战计':i<30?'并战计':'败战计'),quote:'这是三十六计中的“'+c+'”，点击后已切换到对应计策。',note:'三十六计是具体局势中的应变工具；先判断局面，再判断是否适用，不能把计策当成固定套路。',matter:'先明确目标、约束和代价，再看这条计改变的是资源、节奏、注意力还是行动路径。',people:'处理人际时要区分策略与操控：保留对方的尊严、选择权和可退出空间。',history:'历史镜像',historyTitle:'局势与边界'}:readings[i%readings.length];render()};$('chapter-list').appendChild(b);});}
document.querySelectorAll('.section').forEach(b=>b.onclick=()=>{document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));b.classList.add('active');if(b.dataset.section==='sunzi'){renderChapters(chapters,'孙子兵法十三篇','13 篇')}else if(b.dataset.section==='plans'){renderChapters(plans,'三十六计','36 计')}});
document.querySelectorAll('.book').forEach(b=>b.onclick=()=>{if(b.dataset.book==='new'){alert('下一步可以在这里添加书名、作者和目录。');return}document.querySelectorAll('.book').forEach(x=>x.classList.remove('active'));b.classList.add('active');});
document.querySelector('#add-book').onclick=()=>alert('下一步可以在这里添加书名、作者和目录。');
renderChapters(chapters,'孙子兵法十三篇','13 篇');
$('prev-btn').onclick=()=>{index=(index+readings.length-1)%readings.length;render()};$('next-btn').onclick=()=>{index=(index+1)%readings.length;render()};$('history-btn').onclick=()=>{$('history-text').textContent='换一个角度：真正的优势常常在交锋前形成。提前准备事实、节奏和退出方案，能让你不必依赖临场勇气。'};$('copy-quote').onclick=()=>navigator.clipboard?.writeText(readings[index].quote);$('save-card').onclick=save;$('clear-cards').onclick=()=>{notes=[];localStorage.removeItem('兵法-notes');renderRecent()};$('reset-btn').onclick=()=>{if(confirm('确定清空本设备上的所有阅读卡吗？')){$('clear-cards').click();loadDraft();}};$('ask-btn').onclick=()=>{const q=$('question').value.trim();if(!q)return;const r=readings[index];$('answer').classList.remove('hidden');$('answer').innerHTML=`<strong>先拆开看：</strong>你问的是“${q}”。这条原则的核心不是操控对方，而是先识别局势中的阻力。处理事儿时，检查目标、路径和节奏；处理人时，检查对方的顾虑、面子和选择权。<br><br><strong>给你的追问：</strong>如果不要求对方立刻认输，你希望他下一步做出什么可验证的动作？`};$('select-help').onclick=()=>{$('question').focus();$('question').placeholder='把你选中的原文和具体场景粘贴进来……';};render();renderRecent();
